#!/usr/bin/env bash
# Builds the installed tree for the .rpm, the Arch package and the Flatpak
# from the .deb, with one change: NearShare's protobuf bindings and a
# protobuf runtime that matches them.
#
# usage: build-tree.sh <nearshare_*_all.deb> <root>
#
# The .deb's nearshare/proto/*_pb2.py are generated by Ubuntu's protoc for
# Ubuntu's python3-protobuf (see tools/genproto.sh). No other distribution's
# protobuf loads them: Fedora 44 ships protobuf 3.19, older than that code,
# and openSUSE and Arch ship 7.x, which rejects pre-4.x descriptors. No one
# generated version suits all three, so the tree regenerates the bindings
# with grpcio-tools $GRPCIO_TOOLS_VERSION and carries the pure-Python
# protobuf $PROTOBUF_VERSION in /usr/share/nearshare, which the launcher
# already puts first on PYTHONPATH. Needs network access (pip).
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo="$(cd "$here/../.." && pwd)"
[ $# -eq 2 ] || { echo "usage: $0 <nearshare_*_all.deb> <root>" >&2; exit 2; }
deb="$1"
root="$2"
# shellcheck source=/dev/null
. "$here/distro.conf"

dpkg-deb -x "$deb" "$root"
app="$root/usr/share/nearshare"
test -f "$app/nearshare/proto/offline_wire_formats_pb2.py"

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
python3 -m venv "$work/venv"
"$work/venv/bin/pip" install --quiet "grpcio-tools==$GRPCIO_TOOLS_VERSION" "protobuf==$PROTOBUF_VERSION"

# tools/genproto.sh writes into the checkout; copy its output over the
# .deb's bindings, module for module.
bash "$repo/tools/genproto.sh" "$work/venv/bin/python"
n=0
for f in "$repo"/nearshare/proto/*_pb2.py; do
  test -f "$app/nearshare/proto/$(basename "$f")"
  install -m 0644 "$f" "$app/nearshare/proto/"
  n=$((n + 1))
done
[ "$n" -eq 7 ] || { echo "expected 7 protobuf modules, generated $n" >&2; exit 1; }

# The pure-Python wheel (py3-none-any), so the packages stay free of native
# code and architecture-independent.
"$work/venv/bin/pip" download --quiet --no-deps --only-binary=:all: --platform any \
  --implementation py --python-version 3.12 -d "$work/wheel" "protobuf==$PROTOBUF_VERSION"
wheels=("$work"/wheel/protobuf-"$PROTOBUF_VERSION"-py3-none-any.whl)
[ -f "${wheels[0]}" ]
python3 -m zipfile -e "${wheels[0]}" "$app"
test -f "$app/google/protobuf/__init__.py"
if find "$app/google" -name '*.so' | grep . > /dev/null; then
  echo "native code in the protobuf wheel" >&2
  exit 1
fi
# An empty google/__init__.py makes the bundled copy a regular package, so a
# protobuf (or any google.* package) in the distribution's site-packages can
# never take precedence over it in NearShare's process.
: > "$app/google/__init__.py"
find "$app" -name '__pycache__' -prune -exec rm -rf {} +
echo "tree: .deb files, bindings from grpcio-tools $GRPCIO_TOOLS_VERSION, protobuf $PROTOBUF_VERSION"
